    </div>}
    <div className="geometry-note" aria-live="polite">{journey ? geometryLoading ? "Loading service track routes…" : journey.legs.every(l => validTrack(l.routeGeometry)) ? journey.legs.some(l => l.routeGeometrySource === "osm") ? "Mapped service tracks · not live diversions" : "Timetable route · illustrative trains, not live" : "Some track geometry is unavailable; dashed links are schematic" : basemapMode === "earth" ? "Satellite imagery · not live weather" : "OpenStreetMap borders · zoom in for railway tracks"}{journey && !geometryLoading && journey.legs.some(l => !validTrack(l.routeGeometry)) && <button type="button" onClick={() => setGeometryAttempt(attempt => attempt + 1)} style={{ point
    {(tileError || imageryUnavailable) && <div className="map-warning" role="status">{imageryUnavailable ? "Satellite imagery is unavailable. Showing the geographic map instead." : "Some map details are unavailable. Your trip summary is still available."}</div>}
  </>
}
